&lt;p style=&quot;font-family: Helvetica, Arial, sans-serif; font-style: normal; font-weight: 400; color: rgb(0, 0, 0); margin: 0px !important; padding: 0px !important;&quot;&gt;&amp;nbsp;&lt;/p&gt;
